data.query:
query Query($where: ReceiptWhereInput, $orderBy: [ReceiptOrderByInput!], $first: Int, $after: String) {
  receipt(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        receiptAt
        statusId
        status {
          id
          active
          cancelled
          confirmed
          received
        }
        location {
          id
          facilityId
        }
        lines {
          edges {
            node {
              id
              number
              customData
              licensePlates
              quantityPerLicensePlate {
                value
                unitId
              }
              quantity {
                value
                unitId
              }
              workOrderProcessDistributionGroup {
                id
                distributions {
                  edges {
                    node {
                      workOrderProcessId
                    }
                  }
                }
              }
              lotId
              lot {
                number
              }
              inventories {
                edges {
                  node {
                    id
                    inventoryStatusId
                    quantity {
                      value
                    }
                    number
                    masterInventoryId
                    locationId
                    lot {
                      id
                      number
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  receiptStatus {
    edges {
      node {
        id
        name
        active
        cancelled
        confirmed
        pending
        received
        supplierShipped
        system
        usable
        color
        message
      }
    }
  }
  inventoryStatus {
    edges {
      node {
        id
        name
        active
        consigned
        containment
        defective
        loaded
        mergePrevent
        movePrevent
        picked
        productionLoaded
        productionPrevent
        received
        shipPrevent
        shipped
        splitPrevent
        staged
        suspect
        system
        usable
        color
        externalId
        message
      }
    }
  }
  masterInventoryStatus {
    edges {
      node {
        id
        name
        active
        containment
        empty
        loaded
        mergePrevent
        movePrevent
        picked
        productionLoaded
        productionPrevent
        received
        shipPrevent
        shipped
        splitPrevent
        staged
        system
        usable
        color
        externalId
        message
      }
    }
  }
}

query Query($where: ProductionSetupOutputWhereInput, $orderBy: [ProductionSetupOutputOrderByInput!], $first: Int, $after: String) {
  productionSetupOutput(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    total
    edges {
      node {
        id
        producedQuantity
        scrappedQuantity
        remainingBalance
        workcenterId
        workOrderDistributionGroupId
      }
    }
  }
}

data.transform:
const data = $state.context.LOCAL.receipt.lines.edges;
const outputId = $.productionSetupOutput.edges[0].node.id;
const claims = $state.claims;
const suspect = $state.context.REQUEST.DATA.suspect;

const result = data.flatMap(item => {
  const { licensePlates, quantityPerLicensePlate } = item.node;
  const isScrap = item.node.customData?.scrap;
  return Array.from({ length: licensePlates }, (_, i) => ({
  REQUEST:{
    DATA:{
    productionSetupOutputId:outputId,
    licensePlate: i + 1,
    quantity: quantityPerLicensePlate.value,
    unit: quantityPerLicensePlate.unitId,
    productionTypeId: 'Production',
    receiptLineId:item.node.id,
    locationId:$state.context.LOCAL.receipt.location.id

  },
    CLAIMS:claims ,
    ACTION: "PRODUCE",
    OCustomer-DON: {
      "kanban": false,
      "scrap": isScrap,
      "suspect":suspect
    },
  }
}));
});
return(result);

data.mutation:
mutation Mutation($payload: [ReceiptUpdatePayloadInput!]!, $payloadLine: [ReceiptLineUpdatePayloadInput!]!) {
  updateReceipt(payload: $payload) {
    id
    number
    externalId
    statusId
  }
  updateReceiptLine(payload: $payloadLine) {
    id
    number
    externalId
    statusId
  }
}

